const h = $json;
const errors = [];
if (h.ok !== true) errors.push('ok');
if (String(h.service || '') !== 'sm3-media-worker') errors.push('service');
if (String(h.version || '') !== '2.4.0') errors.push('version=' + h.version);
if (String(h.production_edit_contract || '') !== 'SM3_PRODUCTION_EDIT_V1') errors.push('production_edit_contract');
if (String(h.edit_session_contract || '') !== 'SM3_EDIT_SESSION_V1') errors.push('edit_session_contract');
if (h.editor_workspace !== true) errors.push('editor_workspace');
if (h.editor_workspace_read_only !== true) errors.push('editor_workspace_read_only');
if (h.editor_workspace_asset_verified !== true) errors.push('editor_workspace_asset_verified');
if (String(h.editor_workspace_contract || '') !== 'SM3_EDITOR_WORKSPACE_V1') errors.push('editor_workspace_contract');
if (errors.length) throw new Error('WORKER_2_4_0_CONTRACT_MISMATCH:' + errors.join(','));
return {json:{status:'WORKER_2_4_0_CONTRACT_VERIFIED',checked_at:new Date().toISOString()}};

const rows = $input.all().map(i => i.json);
const text = v => String(v || '').trim();
const upper = v => text(v).toUpperCase();
const counts = new Map();
for (const row of rows) {
  const id = text(row.ID_CONTEÚDO);
  if (id) counts.set(id, (counts.get(id) || 0) + 1);
}
const work = [];
const blocked = [];
for (const row of rows) {
  const projectId = text(row.ID_PROJETO);
  const contentId = text(row.ID_CONTEÚDO);
  const variantSetId = text(row.VARIANT_SET_ID);
  const selected = upper(row.SELECTED_VARIANT_ID);
  const sessionId = text(row.EDIT_SESSION_ID);
  const sessionStatus = upper(row.EDIT_SESSION_STATUS);
  const pipeline = upper(row.PIPELINE_STATE);
  const review = upper(row.VARIANT_REVIEW_STATUS);
  const recipeVersion = text(row.EDIT_RECIPE_VERSION);
  const stateVersion = text(row.STATE_VERSION);
  const productionContract = text(row.PRODUCTION_CONTRACT_VERSION);
  const candidate = pipeline === 'EDIT_SESSION_READY' || review === 'OPEN_EDITOR' || Boolean(sessionId);
  if (!candidate) continue;
  const errors = [];
  if (!projectId) errors.push('ID_PROJETO_MISSING');
  if (!contentId) errors.push('ID_CONTEUDO_MISSING');
  if (contentId && counts.get(contentId) !== 1) errors.push('ID_CONTEUDO_NOT_UNIQUE');
  if (!/^VS_[A-Za-z0-9_-]+$/.test(variantSetId)) errors.push('VARIANT_SET_ID_INVALID');
  if (!/^V\d{2}$/.test(selected)) errors.push('SELECTED_VARIANT_ID_INVALID');
  if (!/^ES_[A-Za-z0-9_-]+$/.test(sessionId)) errors.push('EDIT_SESSION_ID_INVALID');
  if (!['OPEN','SAVED','COMPLETED'].includes(sessionStatus)) errors.push('EDIT_SESSION_STATUS=' + (sessionStatus || 'EMPTY'));
  if (pipeline !== 'EDIT_SESSION_READY') errors.push('PIPELINE_STATE=' + (pipeline || 'EMPTY'));
  if (review !== 'OPEN_EDITOR') errors.push('VARIANT_REVIEW_STATUS=' + (review || 'EMPTY'));
  if (recipeVersion !== 'SM3_EDIT_RECIPE_V1') errors.push('EDIT_RECIPE_VERSION=' + (recipeVersion || 'EMPTY'));
  if (stateVersion !== 'SM3_STATE_V5') errors.push('STATE_VERSION=' + (stateVersion || 'EMPTY'));
  if (productionContract !== 'SM3_PRODUCTION_EDIT_V1') errors.push('PRODUCTION_CONTRACT_VERSION=' + (productionContract || 'EMPTY'));
  if (errors.length) {
    blocked.push({project_id:projectId,content_id:contentId,edit_session_id:sessionId,errors});
  } else {
    work.push({route_key:'WORK',project_id:projectId,content_id:contentId,variant_set_id:variantSetId,base_variant_id:selected,edit_session_id:sessionId,expected_status:sessionStatus});
  }
}
if (blocked.length) return [{json:{route_key:'BLOCKED',status:'EDITOR_WORKSPACE_INPUT_BLOCKED',blocked}}];
if (work.length) return work.map(x => ({json:x}));
return [{json:{route_key:'NO_WORK',status:'NO_EDIT_SESSION_READY'}}];

const w = $json;
const request = $('BUILD — WORKSPACE VERIFY QUEUE').all().map(i => i.json).find(x => String(x.edit_session_id || '') === String(w.edit_session_id || ''));
if (!request) throw new Error('EDITOR_WORKSPACE_REQUEST_NOT_FOUND:' + (w.edit_session_id || 'EMPTY'));
const errors = [];
if (w.ok !== true) errors.push('ok');
if (String(w.version || '') !== '2.4.0') errors.push('version=' + w.version);
if (String(w.production_contract_version || '') !== 'SM3_PRODUCTION_EDIT_V1') errors.push('production_contract_version');
if (String(w.workspace_contract_version || '') !== 'SM3_EDITOR_WORKSPACE_V1') errors.push('workspace_contract_version');
if (String(w.edit_session_contract_version || '') !== 'SM3_EDIT_SESSION_V1') errors.push('edit_session_contract_version');
if (String(w.edit_contract_version || '') !== 'SM3_EDIT_RECIPE_V1') errors.push('edit_contract_version');
for (const field of ['project_id','content_id','variant_set_id','edit_session_id']) {
  if (String(w[field] || '') !== String(request[field] || '')) errors.push(field + '_mismatch');
}
if (String(w.base_variant_id || '') !== String(request.base_variant_id || '')) errors.push('base_variant_id_mismatch');
if (String(w.status || '') !== String(request.expected_status || '')) errors.push('status_mismatch');
if (!Number.isInteger(Number(w.current_revision)) || Number(w.current_revision) < 1) errors.push('current_revision');
if (!/^[a-f0-9]{64}$/.test(String(w.state_etag || ''))) errors.push('state_etag');
if (w.read_only !== true) errors.push('read_only');
if (!w.recipe || typeof w.recipe !== 'object') errors.push('recipe');
if (!w.base_variant || typeof w.base_variant !== 'object') errors.push('base_variant');
if (w.preview?.verified !== true) errors.push('preview_verified');
if (!/^[a-f0-9]{64}$/.test(String(w.preview?.sha256 || ''))) errors.push('preview_sha256');
if (!(Number(w.preview?.bytes || 0) > 0)) errors.push('preview_bytes');
if (String(w.preview?.contract_version || '') !== 'SM3_VARIANT_PREVIEW_V1') errors.push('preview_contract');
for (const key of ['timeline','framing','text_overlays','identity_application','color_treatment','transitions','audio','ai_revision_request']) {
  if (w.capabilities?.[key] !== true) errors.push('capability_' + key);
}
for (const key of ['non_destructive','preserve_subject_required','original_media_immutable','base_variant_immutable','final_approval_required','publish_from_preview_forbidden']) {
  if (w.constraints?.[key] !== true) errors.push('constraint_' + key);
}
if (errors.length) throw new Error('EDITOR_WORKSPACE_CONTRACT_MISMATCH:' + errors.join(','));
return {json:w};

const state = $json;
const workspace = $('ASSERT — WORKSPACE CONTRACT').all().map(i => i.json).find(x => String(x.edit_session_id || '') === String(state.edit_session_id || ''));
if (!workspace) throw new Error('EDITOR_WORKSPACE_RESPONSE_NOT_FOUND:' + (state.edit_session_id || 'EMPTY'));
for (const field of ['project_id','content_id','variant_set_id','base_variant_id','edit_session_id','status']) {
  if (String(state[field] || '') !== String(workspace[field] || '')) throw new Error('EDITOR_WORKSPACE_PERSIST_MISMATCH:' + field);
}
if (Number(state.current_revision || 0) !== Number(workspace.current_revision || 0)) throw new Error('EDITOR_WORKSPACE_PERSIST_REVISION_MISMATCH');
if (String(state.production_contract_version || '') !== 'SM3_PRODUCTION_EDIT_V1') throw new Error('EDITOR_WORKSPACE_PERSIST_PRODUCTION_CONTRACT');
if (String(state.edit_session_contract_version || '') !== 'SM3_EDIT_SESSION_V1') throw new Error('EDITOR_WORKSPACE_PERSIST_SESSION_CONTRACT');
if (String(state.edit_contract_version || '') !== 'SM3_EDIT_RECIPE_V1') throw new Error('EDITOR_WORKSPACE_PERSIST_RECIPE_CONTRACT');
if (String(state.selection_evidence?.preview_sha256 || '') !== String(workspace.preview?.sha256 || '')) throw new Error('EDITOR_WORKSPACE_PERSIST_PREVIEW_HASH_MISMATCH');
if (JSON.stringify(state.recipe) !== JSON.stringify(workspace.recipe)) throw new Error('EDITOR_WORKSPACE_PERSIST_RECIPE_MISMATCH');
const p = encodeURIComponent(state.project_id), c = encodeURIComponent(state.content_id), s = encodeURIComponent(state.edit_session_id);
return {json:{status:'EDITOR_WORKSPACE_VERIFIED',project_id:state.project_id,content_id:state.content_id,edit_session_id:state.edit_session_id,base_variant_id:state.base_variant_id,current_revision:Number(state.current_revision),state_etag:workspace.state_etag,preview_sha256:workspace.preview.sha256,editor_url:'http://localhost:8090/production/editor/'+p+'/'+c+'/'+s,workspace_url:'http://localhost:8090/production/editor-workspace/'+p+'/'+c+'/'+s}};

const verified = $input.all().map(i => i.json);
if (!verified.length) throw new Error('EDITOR_WORKSPACE_AUDIT_EMPTY');
return [{json:{status:'EDITOR_WORKSPACE_BOOTSTRAP_VERIFIED',verified_count:verified.length,verified,verified_at:new Date().toISOString(),next_stage:'07E_MANUAL_EDIT_SAVE'}}];
